from .curriculum_a0_extra import _ex_bundle


def _make_lesson(
    lid: str,
    title: str,
    skills: list[str],
    minutes: int,
    showcase: list[dict],
    explanation: str,
    rule: str,
    examples: list[dict],
    vocab: list[dict],
    exercises: list[dict],
) -> dict:
    return {
        "id": lid,
        "kind": "lesson",
        "title": title,
        "skill_focus": skills,
        "estimated_minutes": minutes,
        "showcase": showcase,
        "simple_explanation": explanation,
        "rule_name": rule,
        "examples": examples,
        "vocab": vocab,
        "exercises": _ex_bundle(lid, rule, exercises),
    }


